class TestTaskComplexity:
    """Verify task complexity enum behavior and classification logic."""

    def test_complexity_ordering(self):
        """Verify complexity levels have correct ordering for priority."""
        complexities = [
            TaskComplexity.LOW,
            TaskComplexity.MEDIUM,
            TaskComplexity.HIGH,
            TaskComplexity.CRITICAL,
        ]
        # Verify they can be compared and ordered
        sorted_complexities = sorted(complexities, key=lambda c: c.value)
        assert sorted_complexities == complexities

    def test_complexity_values(self):
        """Verify string representations match expected values."""
        assert TaskComplexity.LOW.value == "low"
        assert TaskComplexity.MEDIUM.value == "medium"
        assert TaskComplexity.HIGH.value == "high"
        assert TaskComplexity.CRITICAL.value == "critical"

    def test_complexity_from_string(self):
        """Verify parsing from string works correctly."""
        assert TaskComplexity("low") == TaskComplexity.LOW
        assert TaskComplexity("medium") == TaskComplexity.MEDIUM
        assert TaskComplexity("high") == TaskComplexity.HIGH
        assert TaskComplexity("critical") == TaskComplexity.CRITICAL

    def test_complexity_invalid_string(self):
        """Verify invalid complexity strings raise ValueError."""
        with pytest.raises(ValueError):
            TaskComplexity("ultra")


