class TestPriorityQueue:
    """Verify heap-based priority queue operations."""

    @pytest.mark.asyncio
    async def test_heap_push_pop_order(self, task_arbiter, sample_tasks):
        """Verify tasks are popped in correct priority order."""
        # Push tasks in reverse priority order
        await task_arbiter.submit_task(sample_tasks["low"])
        await task_arbiter.submit_task(sample_tasks["medium"])
        await task_arbiter.submit_task(sample_tasks["high"])
        await task_arbiter.submit_task(sample_tasks["critical"])

        # Pop should return highest priority first
        task1 = await task_arbiter.get_next_task()
        assert task1.task_id == "crit_001"  # CRITICAL priority

        task2 = await task_arbiter.get_next_task()
        assert task2.task_id == "high_001"  # HIGH priority

        task3 = await task_arbiter.get_next_task()
        assert task3.task_id == "med_001"  # MEDIUM priority

        task4 = await task_arbiter.get_next_task()
        assert task4.task_id == "low_001"  # LOW priority

    @pytest.mark.asyncio
    async def test_heap_empty_pop(self, task_arbiter):
        """Verify popping from empty queue returns None."""
        task = await task_arbiter.get_next_task()
        assert task is None

    @pytest.mark.asyncio
    async def test_heap_duplicate_detection(self, task_arbiter, sample_tasks):
        """Verify O(1) duplicate detection prevents double submission."""
        await task_arbiter.submit_task(sample_tasks["low"])
        # Submit same task again
        result = await task_arbiter.submit_task(sample_tasks["low"])
        assert result is False  # Duplicate rejected

        # Queue should still have only one task
        assert task_arbiter.queue_size() == 1

    @pytest.mark.asyncio
    async def test_heap_priority_inversion(self, task_arbiter):
        """Verify no priority inversion occurs with mixed priorities."""
        now = datetime.utcnow()
        tasks = [
            Task(
                task_id=f"task_{i}",
                name=f"test_{i}",
                complexity=TaskComplexity.LOW if i % 2 == 0 else TaskComplexity.HIGH,
                priority=TaskPriority.NORMAL if i % 2 == 0 else TaskPriority.CRITICAL,
                created_at=now,
            )
            for i in range(10)
        ]

        # Submit in random order
        import random
        random.shuffle(tasks)
        for task in tasks:
            await task_arbiter.submit_task(task)

        # Verify all CRITICAL tasks come before NORMAL tasks
        previous_priority = TaskPriority.IMMEDIATE
        for _ in range(10):
            task = await task_arbiter.get_next_task()
            assert task.priority.value <= previous_priority.value
            previous_priority = task.priority

    @pytest.mark.asyncio
    async def test_heap_large_batch(self, task_arbiter):
        """Verify heap performance with large batch of tasks."""
        now = datetime.utcnow()
        tasks = [
            Task(
                task_id=f"batch_{i}",
                name=f"batch_test_{i}",
                complexity=TaskComplexity.LOW,
                priority=TaskPriority.NORMAL,
                created_at=now,
            )
            for i in range(1000)
        ]

        # Submit all tasks
        for task in tasks:
            await task_arbiter.submit_task(task)

        assert task_arbiter.queue_size() == 1000

        # Retrieve all tasks
        retrieved = []
        for _ in range(1000):
            task = await task_arbiter.get_next_task()
            if task:
                retrieved.append(task)

        assert len(retrieved) == 1000
        # Verify no duplicates
        task_ids = [t.task_id for t in retrieved]
        assert len(task_ids) == len(set(task_ids))


