class TestThreadSafety:
    """Verify thread-safe async operations with asyncio.Lock."""

    @pytest.mark.asyncio
    async def test_concurrent_submissions(self, task_arbiter):
        """Verify concurrent task submissions don't corrupt state."""
        now = datetime.utcnow()
        tasks = [
            Task(
                task_id=f"concurrent_{i}",
                name=f"concurrent_test_{i}",
                complexity=TaskComplexity.LOW,
                priority=TaskPriority.NORMAL,
                created_at=now,
            )
            for i in range(100)
        ]

        # Submit tasks concurrently
        async def submit_task(task):
            return await task_arbiter.submit_task(task)

        tasks_coro = [submit_task(task) for task in tasks]
        results = await asyncio.gather(*tasks_coro)

        # All should succeed (no duplicates)
        assert all(results)
        assert task_arbiter.queue_size() == 100

    @pytest.mark.asyncio
    async def test_concurrent_submit_and_pop(self, task_arbiter):
        """Verify concurrent submit and pop operations are safe."""
        now = datetime.utcnow()

        async def submitter():
            for i in range(50):
                task = Task(
                    task_id=f"thread_safe_{i}",
                    name=f"safe_test_{i}",
                    complexity=TaskComplexity.LOW,
                    priority=TaskPriority.NORMAL,
                    created_at=now,
                )
                await task_arbiter.submit_task(task)
                await asyncio.sleep(0.001)

        async def popper():
            retrieved = []
            for _ in range(50):
                task = await task_arbiter.get_next_task()
                if task:
                    retrieved.append(task)
                await asyncio.sleep(0.001)
            return retrieved

        # Run concurrently
        submit_task = asyncio.create_task(submitter())
        pop_task = asyncio.create_task(popper())

        await asyncio.gather(submit_task, pop_task)

        # Verify no corruption
        assert task_arbiter.queue_size() >= 0

    @pytest.mark.asyncio
    async def test_lock_contention(self, task_arbiter):
        """Verify lock contention doesn't cause deadlocks."""
        now = datetime.utcnow()
        tasks = [
            Task(
                task_id=f"lock_test_{i}",
                name=f"lock_test_{i}",
                complexity=TaskComplexity.LOW,
                priority=TaskPriority.NORMAL,
                created_at=now,
            )
            for i in range(10)
        ]

        # Multiple concurrent operations
        async def mixed_operation():
            for task in tasks:
                await task_arbiter.submit_task(task)
                await task_arbiter.get_next_task()
                await asyncio.sleep(0.001)

        # Run multiple concurrent mixed operations
        coros = [mixed_operation() for _ in range(5)]
        await asyncio.gather(*coros)

        # Should not deadlock
        assert True


