# Property-Based Tests
# =============================================================================

class TestProperties:
    """Verify invariants and properties hold under various conditions."""

    @pytest.mark.asyncio
    async def test_queue_size_invariant(self, task_arbiter):
        """Verify queue size always equals number of unique tasks."""
        now = datetime.utcnow()
        tasks = [
            Task(
                task_id=f"prop_{i}",
                name=f"prop_test_{i}",
                complexity=TaskComplexity.LOW,
                priority=TaskPriority.NORMAL,
                created_at=now,
            )
            for i in range(50)
        ]

        for task in tasks:
            await task_arbiter.submit_task(task)

        assert task_arbiter.queue_size() == 50

        # Pop half
        for _ in range(25):
            await task_arbiter.get_next_task()

        assert task_arbiter.queue_size() == 25

    @pytest.mark.asyncio
    async def test_no_duplicate_tasks(self, task_arbiter):
        """Verify no duplicate tasks can exist in queue."""
        now = datetime.utcnow()
        task = Task(
            task_id="unique_test",
            name="unique",
            complexity=TaskComplexity.LOW,
            priority=TaskPriority.NORMAL,
            created_at=now,
        )

        # Submit twice
        await task_arbiter.submit_task(task)
        result = await task_arbiter.submit_task(task)

        assert result is False  # Duplicate rejected
        assert task_arbiter.queue_size() == 1

    @pytest.mark.asyncio
    async def test_priority_order_invariant(self, task_arbiter):
        """Verify tasks are always returned in priority order."""
        now = datetime.utcnow()
        priorities = [
            TaskPriority.LOW,
            TaskPriority.NORMAL,
            TaskPriority.HIGH,
            TaskPriority.CRITICAL,
            TaskPriority.IMMEDIATE,
        ]

        tasks = []
        for i, priority in enumerate(priorities):
            task = Task(
                task_id=f"order_{i}",
                name=f"order_test_{i}",
                complexity=TaskComplexity.LOW,
                priority=priority,
                created_at=now,
            )
            tasks.append(task)

        # Submit in reverse order
        for task in reversed(tasks):
            await task_arbiter.submit_task(task)

        # Pop should return in correct order
        previous_priority_value = float('inf')
        for _ in range(len(tasks)):
            task = await task_arbiter.get_next_task()
            assert task.priority.value <= previous_priority_value
            previous_priority_value = task.priority.value


