# Singleton Pattern Tests
# =============================================================================

class TestSingleton:
    """Verify get_task_arbiter returns singleton instance."""

    def test_singleton_instance(self):
        """Verify get_task_arbiter returns same instance."""
        arbiter1 = get_task_arbiter()
        arbiter2 = get_task_arbiter()
        assert arbiter1 is arbiter2

    def test_singleton_thread_safety(self):
        """Verify singleton is thread-safe."""
        instances = []

        def get_instance():
            instances.append(get_task_arbiter())

        threads = [threading.Thread(target=get_instance) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        # All should be the same instance
        assert all(i is instances[0] for i in instances)


